use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAccessTemporalCodeTempSecondFactorSeedExpirationAccessor trait.
 *
 * Covers null default, string/VO assignment via withTempSecondFactorSeedExpiration,
 * getTempSecondFactorSeedExpiration/tempSecondFactorSeedExpiration accessors, and isTempSecondFactorSeedExpirationChanged with/without original.
 */
class UserAccessTemporalCodeTempSecondFactorSeedExpirationAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTempSecondFactorSeedExpiration creates a new instance with the TempSecondFactorSeedExpiration set
     * from a string value, and getTempSecondFactorSeedExpiration returns the primitive string.
     */
    public function testWithTempSecondFactorSeedExpirationFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeTempSecondFactorSeedExpirationAccessorUnitTest();

        // Act
        $result = $holder->withTempSecondFactorSeedExpiration((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->getTempSecondFactorSeedExpiration());
    }
    /**
     * Asserts that withtempSecondFactorSeedExpiration has access to the value object
     * from a string value, and getTempSecondFactorSeedExpiration returns the primitive string.
     */
    public function testWithTempSecondFactorSeedExpirationFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeTempSecondFactorSeedExpirationAccessorUnitTest();

        // Act
        $result = $holder->withTempSecondFactorSeedExpiration((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals((new \DateTimeImmutable('1980-08-20T14:32:45.123Z')), $result->tempSecondFactorSeedExpiration()->value());
    }
    public function testChangedTempSecondFactorSeedExpiration(): void
    {
        // Arrange
        $holder = new ImplWithUserAccessTemporalCodeTempSecondFactorSeedExpirationAccessorUnitTest();
        $original = $holder->withTempSecondFactorSeedExpiration( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $same = $holder->withTempSecondFactorSeedExpiration( (new \DateTimeImmutable('1980-08-20T14:32:45.123Z')));
        $modified = $holder->withTempSecondFactorSeedExpiration((new \DateTimeImmutable('1981-09-06T14:32:45.123Z')));

        // Act
        $unchanged = $holder->isTempSecondFactorSeedExpirationChanged();
        $withSame = $original->isTempSecondFactorSeedExpirationChanged( $same );
        $withDiferent = $original->isTempSecondFactorSeedExpirationChanged( $modified );

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
